  if(project.performers.length-selected.size<1){toast('Keep at least one performer in your project.');return;}
  remember();const removed=new Set(selected);project.routes=project.routes.filter(r=>!removed.has(r.performerId));project.actions.forEach(a=>a.performerIds=a.performerIds.filter(id=>!removed.has(id)));project.rehearsals.forEach(r=>r.performerIds=r.performerIds.filter(id=>!removed.has(id)));project.props.forEach(prop=>{prop.attachments=(prop.attachments||[]).filter(e=>!removed.has(e.performerId));});project.performers=project.performers.filter(p=>!selected.has(p.id));project.performers.forEach((p,i)=>p.number=i+1);project.formations.forEach(f=>{f.positions=f.positions.filter(p=>!selected.has(p.performerId));f.status='draft';});selected.clear();commit('Performer removed from formations and prop assignments. Undo is available.');
