  if(view==='spatial'){disableFollow();camera3D.target=[ps.reduce((sum,p)=>sum+p.x,0)/ps.length,.8,-ps.reduce((sum,p)=>sum+p.z,0)/ps.length];const span=Math.max(2,...ps.map(p=>Math.abs(p.x-camera3D.target[0])*2+2),...ps.map(p=>Math.abs(-p.z-camera3D.target[2])*2+2));camera3D.zoom=clamp(Math.max(project.stage.width,project.stage.depth)/span,.5,3);Object.assign(stage3D?.camera||{},camera3D);stage3D?.update(stageProject(),samplePerformance(project,time),{ghosts:currentGhosts(),analysis:currentAnalysis()});render();return;}
