let gainNode;
function getAudioContext(){if(!audioContext){audioContext=createAudioContext();gainNode=audioContext.createGain();gainNode.gain.value=muted?0:.65;gainNode.connect(audioContext.destination);}return audioContext;}
function demoAudio(){
  const ctx=getAudioContext(),sr=ctx.sampleRate,duration=96;
  const buffer=ctx.createBuffer(1,sr*duration,sr),out=buffer.getChannelData(0);
  // Original procedural instrumental. The displayed waveform is derived from this buffer.
  const chords=[[130.81,164.81,196],[110,130.81,164.81],[87.31,110,130.81],[98,123.47,146.83]];
  for(let i=0;i<out.length;i++){
    const t=i/sr,beat=t%.5,chord=chords[Math.floor(t/8)%4];
    const fade=Math.min(1,t/3,(duration-t)/4);
    let value=Math.sin(2*Math.PI*(55*beat+55*.03*(1-Math.exp(-beat/.03))))*Math.exp(-beat*24)*.2;
    const note=chord[Math.floor(t*2)%3]*2;
    value+=(Math.sin(2*Math.PI*note*t)+.3*Math.sin(2*Math.PI*note*2*t))*Math.exp(-beat*7)*.055;
    chord.forEach(hz=>value+=Math.sin(2*Math.PI*hz*t)*(.5+.5*Math.sin(t*.35))*.025);
    out[i]=value*fade;
  }
  return buffer;
}
function computeWave(buffer){const channel=buffer.getChannelData(0);wave=Array.from({length:340},(_,i)=>{const start=Math.floor(i/340*channel.length),end=Math.floor((i+1)/340*channel.length);let peak=0;for(let j=start;j<end;j+=Math.max(1,Math.floor((end-start)/200)))peak=Math.max(peak,Math.abs(channel[j]));return Math.min(1,peak*2.5);});}
function musicBuffer(){if(project.music.mode==='silent')return null;if(project.music.mode==='file')return audioBuffer;demoBuffer||=demoAudio();return demoBuffer;}
async function play(){
 if(handleShowPlay())return;
 try{primeNativePlayback();}catch{}
 try{const token=++playbackToken,currentProject=project.id;let ctx=null,buffer=null;
  if(project.music.mode!=='silent'){try{ctx=getAudioContext();await ctx.resume();buffer=musicBuffer();}catch{ctx=null;toast('Audio is unavailable. Playing a silent visual rehearsal.');}}
  if(token!==playbackToken||currentProject!==project.id)return;
  if(buffer&&project.music.mode==='demo'){computeWave(buffer);const svg=$('.audio-lane svg');if(svg)svg.outerHTML=waveformSVG();}
  if(project.music.mode==='file'&&!buffer)toast('Uploaded music is unavailable here. Visual rehearsal still works; restore the original audio to hear it.');
  if(time>=project.duration)time=0;playing=true;clockStart=performance.now();clockOffset=time;
  if(ctx&&buffer){const slice=audioSlice(project,buffer.duration,time,project.duration);if(slice){audioSource=ctx.createBufferSource();audioSource.buffer=buffer;audioSource.playbackRate.value=rate;audioSource.connect(gainNode);audioStart=ctx.currentTime;audioSource.start(ctx.currentTime+slice.delay/rate,slice.offset,slice.duration);}}
  playbackPacer.reset(performance.now());lastHUD=-Infinity;updatePlayButton();cancelAnimationFrame(playbackFrame);playbackFrame=requestAnimationFrame(tick);syncEnsembleTools(true);
 }catch(error){playing=false;toast(error.message||'Could not start playback.');updatePlayButton();}
}
function clockTime(){return clockOffset+(audioSource?audioContext.currentTime-audioStart:(performance.now()-clockStart)/1000)*rate;}
function pause(options:{fromShow?:boolean}={}){const wasPlaying=playing;playbackToken++;cancelAnimationFrame(playbackFrame);if(playing)time=clamp(clockTime(),0,project.duration);playing=false;if(!options?.fromShow)pauseShowForEditor();syncReference(time,false,rate);if(audioSource){try{audioSource.stop();}catch{}audioSource.disconnect();audioSource=null;}updatePlayButton();playbackView?.update(project,time,{playing:false,active,focused:document.activeElement,hud:!document.body.classList.contains('stage-fullscreen')||document.body.classList.contains('fullscreen-with-timeline')});syncEnsembleTools(wasPlaying);}
function updatePlayButton(){const show=showState(),inBreak=show?.status==='break',pausedBreak=show?.status==='paused-break';document.body.classList.toggle('is-playing',playing);try{syncNativePlayback();}catch{}$$('[data-action="play"]').forEach(b=>{b.innerHTML=icon(playing||inBreak?'pause':'play');b.setAttribute('aria-label',`${inBreak?'Pause intermission':pausedBreak?'Resume intermission':playing?'Pause':'Play'} (Space)`);});}
function seek(t,reset=true,options:{fromShow?:boolean;formationId?:string;time?:number}={}){pause(options);time=clamp(t,0,project.duration);const f=lastMatch(project.formations,f=>f.time<=time)||project.formations[0];if(active!==f.id){active=f.id;selected.clear();if(reset)render();}updatePlayback(true);syncEnsembleTools(true);}
function tick(now){
  if(!playing)return;
  time=clockTime();
  if(showBoundary(time,project.id)){pause();void advanceShow().catch(error=>toast(error.message));return;}
  if(time>=(loop&&loopRegion?loopRegion.end:project.duration)){
    if(loop){pause();time=loopRegion?.start||0;play();return;}
    pause();time=project.duration;updatePlayback(true);return;
  }
  if(playbackPacer.due(now)){
    const started=performance.now(),fullscreen=document.body.classList.contains('stage-fullscreen');
    const current=lastMatch(project.formations,f=>f.time<=time)||project.formations[0];
    if(active!==current.id){
      active=current.id;selected.clear();
      if(!fullscreen){refreshInspector();$$('[data-formation]').forEach(node=>node.classList.toggle('active',node.dataset.formation===active));}
      const heading=$('.canvas-heading h1');if(heading)heading.textContent=current.name;
      const status=$('.canvas-status');if(status)status.innerHTML=icon(current.status==='approved'?'lock':'check')+(current.status==='approved'?'Approved':'Draft formation');
      const stage=$('#stage-svg');if(stage)stage.setAttribute('aria-label',`${current.name} formation on ${project.stage.width} by ${project.stage.depth} meter stage`);
      const subtitle=$('.canvas-subtitle');if(subtitle)subtitle.textContent=`${project.performers.length} performers · ${timecode(current.time)}`;
    }
    updatePlayback(true);
    playbackPacer.record(now,performance.now()-started+(view==='spatial'?last3DCost:0));last3DCost=0;
  }
  playbackFrame=requestAnimationFrame(tick);
}

function updatePlayback(sample=false){
  if(!playing)refreshTimelineTools();
  syncReference(time,playing,rate);
  const paths=$('#movement-paths');if(paths&&paths.dataset.formationId!==active){paths.innerHTML=renderMovementPaths(project,form(),{showPaths,selected,editPaths:tool==='path',readOnly});paths.dataset.formationId=active;const title=$('.canvas-heading h1');if(title)title.textContent=form().name;}
  const positions=sample||playing?samplePerformance(project,time):undefined;
  playbackView||=createPlaybackView($('#app'));
  const now=performance.now(),visible=!document.body.classList.contains('stage-fullscreen')||document.body.classList.contains('fullscreen-with-timeline'),hud=visible&&(!playing||now-lastHUD>=100);if(hud){lastHUD=now;if(playing)refreshTimelineTools();}
  const effective=currentView(positions),ghosts=currentGhosts(),scene=stage3D&&positions?stageProject(positions):null;
  playbackView.update(project,time,{positions:view==='2d'?positions:undefined,geometryPositions:positions,geometryIssues:scene?.sceneSafety,state:{...effective,ghosts},playing,active,focused:document.activeElement,hud});
  const zoomLabel=$('.zoom-label'),zoomText=`${Math.round(effective.zoom*100)}%`;if(zoomLabel&&zoomLabel.textContent!==zoomText)zoomLabel.textContent=zoomText;
  if(positions){const transform=$('#stage-transform');if(transform&&(effective.aids.follow||effective.directed))transform.setAttribute('transform',stageTransform(project,effective.pan,effective.zoom,mirror,rotation,flip));if(stage3D){Object.assign(stage3D.camera,effective.camera);stage3D.update(scene,positions,{ghosts,analysis:effective.analysis,showGrid:effective.showGrid,labels:effective.labels});}}
  syncEnsembleTools();
}

let audioDBPending;
async function getDB(){if(audioDB)return audioDB;if(audioDBPending)return audioDBPending;audioDBPending=new Promise((resolve,reject)=>{let settled=false;const req=indexedDB.open('choryn-media',1),timer=setTimeout(()=>fail(Error('Audio storage timed out. Close other studio tabs and retry.')),10000),fail=error=>{if(settled)return;settled=true;clearTimeout(timer);reject(error);};req.onupgradeneeded=()=>req.result.createObjectStore('audio');req.onblocked=()=>fail(Error('Audio storage is blocked by another tab.'));req.onsuccess=()=>{if(settled){req.result.close();return;}settled=true;clearTimeout(timer);audioDB=req.result;audioDB.onversionchange=()=>{audioDB.close();audioDB=null;};resolve(audioDB);};req.onerror=()=>fail(req.error);}).finally(()=>audioDBPending=null);return audioDBPending;}
async function putAudio(blob,id=project.id){const db=await getDB();return new Promise((resolve,reject)=>{const tx=db.transaction('audio','readwrite');tx.objectStore('audio').put(blob,id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('Audio storage transaction cancelled.'));});}
async function storedAudio(id){try{const db=await getDB();return await new Promise<Blob>((resolve,reject)=>{const request=db.transaction('audio').objectStore('audio').get(id);request.onsuccess=()=>resolve(request.result||null);request.onerror=()=>reject(request.error);});}catch{return null;}}
async function removeAudio(id){try{const db=await getDB();const tx=db.transaction('audio','readwrite');tx.objectStore('audio').delete(id);}catch{}}
let audioLoadToken=0;
async function loadAudio(){const token=++audioLoadToken,id=project.id;audioBuffer=null;persistedAudio=false;wave=[];if(!project.audioName||readOnly)return;try{const blob=await storedAudio(id);if(blob){const decoded=await getAudioContext().decodeAudioData(await blob.arrayBuffer());if(token!==audioLoadToken||project.id!==id)return;audioBuffer=decoded;computeWave(audioBuffer);persistedAudio=true;}}catch{if(project.id===id)toast('Saved music could not be loaded. Upload it again.');}}
async function switchProject(id,options:{fromShow?:boolean;formationId?:string;time?:number}={}){pause(options);clearTimeout(saveTimer);if(!readOnly){const index=projects.findIndex(p=>p.id===project.id);if(index>=0)projects[index]=project;try{writeCollection();}catch{toast('Could not save before switching. Export a backup.');}}const target=projects.find(p=>p.id===id);if(!target){toast('That project is no longer available. Open Projects to choose another.');return;}project=target;try{localStorage.setItem('choryn.activeProject',project.id);}catch{}readOnly=false;if(location.hash)historyReplace();active=project.formations[0].id;time=0;history=[];future=[];selected.clear();await loadAudio();render();}
