// Phones and tablets get the system share sheet (Files, AirDrop, Drive…);
// desktops download. If the export outlived the tap that started it, a
// "ready" sheet supplies a fresh tap for sharing.
let pendingShare:File|null=null;
function download(content,name,type){
  const blob=content instanceof Blob&&(!type||content.type===type)?content:new Blob([content],{type}),safe=String(name).replace(/[<>:"/\\|?*]/g,'-');
  void saveFile(blob,safe,{type,download:saveToDevice,offer:file=>{pendingShare=file;openDialog('Your file is ready.',`<p class="modal-intro">${esc(file.name)} · ${(file.size/1048576).toFixed(file.size<1048576?2:1)} MB</p><div class="modal-footer"><button class="button" data-action="save-ready">${icon('export')}Save to device</button><button class="button primary" data-action="share-ready">${icon('share')}Share…</button></div>`);}});
}
