function printSheets(){
  const win=window.open('','_blank');if(!win){toast('Allow the print window, then try again.');return;}
  win.document.write(`<!doctype html><html><head><title>${esc(project.name)} — CHORYN rehearsal sheets</title><style>body{font:12px Arial;color:#272330;margin:30px}h1{font-size:24px}h2{font-size:19px}p{white-space:pre-line}section{break-after:page}svg{width:100%;max-height:480px}table{border-collapse:collapse;width:100%}td,th{text-align:left;padding:5px 8px;border-bottom:1px solid #ddd}header{display:flex;justify-content:space-between}.notes{color:#665e73}button{padding:10px 20px;margin-bottom:20px}@media print{button{display:none}body{margin:0}section:last-child{break-after:auto}}@page{size:A4 portrait;margin:14mm}</style></head><body><button onclick="window.print()">Print / Save as PDF</button>${project.formations.map((f,i)=>`<section><header><h1>CHORYN / ${esc(project.name)}</h1><p>${i+1} / ${project.formations.length}</p></header>${exportSVG(f)}<h2>${esc(f.name)} · ${timecode(f.time)}</h2><p class="notes">${esc(f.notes)}</p><table><thead><tr><th>#</th><th>Performer</th><th>Group</th><th>X (m)</th><th>Z (m)</th><th>Facing</th><th>Visible</th></tr></thead><tbody>${samplePerformance(project,f.time).map(p=>{const perf=project.performers.find(q=>q.id===p.performerId);return `<tr><td>${perf.number}</td><td>${esc(perf.name)}</td><td>${esc(perf.group)}</td><td>${shortNum(p.x)}</td><td>${shortNum(p.z)}</td><td>${p.facing}°</td><td>${p.visible===false?'Offstage':'Visible'}</td></tr>`;}).join('')}</tbody></table>${i===0?`<h3>Project notes</h3><p class="notes">${esc(project.notes)}</p>`:''}</section>`).join('')}</body></html>`);win.document.close();closeDialog();
}

