const replaceProject=(next,message,options:{formationId?:string;time?:number}={})=>{if(readOnly)return;next=applyReorderRelations(project,cleanLinks(cleanEnsemble(next)));assertEnsembleEdits(project,next);enforceConstraints(next,project);assertProductionLocks(project,next);const valid=validateProject(next);pause();remember();project=valid;if(options.formationId&&project.formations.some(f=>f.id===options.formationId))active=options.formationId;if(!project.formations.some(f=>f.id===active))active=project.formations[0].id;time=clamp(options.time??time,0,project.duration);if(loopRegion){loopRegion.end=Math.min(loopRegion.end,project.duration);if(loopRegion.start>=loopRegion.end){loopRegion=null;loop=false;}}commit(message);};

