 return [command('Production workspace','Studio',()=>productionDialog(),'collision health smart transition motion alignment ripple linked tracks stage CAD lighting costume camera performer exports'),command('Formation comparison and heatmaps','Analysis',analysisDialog,'travel spacing compare overlay'),...actions.map(([title,action,shortcut])=>command(title,'Studio',()=>action==='fullscreen-action'?dispatchTool('data-power','fullscreen'):dispatchTool('data-action',action),'',shortcut)),command('Export performance video','Export',()=>dispatchTool('data-power','video'),'mp4 webm recording'),command('Undo','Edit',()=>undo(),'','Ctrl/⌘ Z',readOnly||!history.length,'No edit to undo'),command('Redo','Edit',()=>undo(true),'','Ctrl/⌘ Shift Z',readOnly||!future.length,'No edit to redo'),...['duplicate','split','copy','paste','cut','delete'].map(action=>command(action[0].toUpperCase()+action.slice(1)+' selected timeline clip','Timeline',()=>runTimelineCommand(action),'formation sequence', '',readOnly&&action!=='copy','Read-only snapshot')),command('Create formation','Edit',()=>dispatchTool('data-action','new-formation'),'add shape', '',readOnly,'Read-only snapshot'),...project.formations.map((f,i)=>command('Go to '+f.name,'Formations',()=>{mode='formation';selectFormation(f.id);},`sequence ${i+1} ${f.time}s`)),...project.performers.map(p=>command('Select '+p.name,'Performers',()=>{mode='formation';selected=new Set([p.id]);render();propertiesDialog();},`${p.group} ${p.role} ${(p.tags||[]).join(' ')}`))];
